use std::any::{Any, TypeId};
use std::collections::HashMap;
use std::sync::{Arc, OnceLock};

#[derive(Default)]
pub struct Registry(HashMap<TypeId, Arc<dyn Any + Send + Sync>>);

impl Registry {
    pub fn insert<T: Any + Send + Sync>(&mut self, svc: Arc<T>) {
        self.0.insert(TypeId::of::<T>(), svc);
    }
    pub fn get<T: Any + Send + Sync>(&self) -> Option<Arc<T>> {
        self.0.get(&TypeId::of::<T>())?.clone().downcast::<T>().ok()
    }
}

static LOCATOR: OnceLock<Registry> = OnceLock::new();

